from pathlib import Path
import base64,hashlib,json
assert Path('/proc/sys/kernel/random/boot_id').read_text().strip()=='be1baaaa-47fc-41f5-8255-8f7092c01653'
root=Path('/var/tmp/gts9-test352');root.mkdir(exist_ok=False)
(root/'tools').mkdir()
for name,encoded in PAYLOAD.items():
 data=base64.b64decode(encoded);assert hashlib.sha256(data).hexdigest()==SHA[name]
